73: function respawnBot(bot,index){const blue=bot.userData.team==='blue',positions=blue?[[-7,-23],[-4,-20],[-8,-17]]:[[7,23],[4,20],[8,17],[7,-22],[5,-18],[8,-14]],p=positions[index%positions.length];bot.position.set(p[0]+(Math.random()-.5)*1.8,0,p[1]+(Math.random()-.5)*2);bot.rotation.y=blue?Math.PI:0;bot.visible=true;bot.userData.hp=100;bot.userData.alive=true;bot.userData.fire=.7+Math.random()*1.8;bot.userData.think=.2;}
