76: function setWeapon(index){weaponIndex=index;const w=weapons[index];$('weaponName').textContent=w.name;$('weaponMode').textContent=w.mode;$('ammoMag').textContent=w.mag;$('ammoRes').textContent='/ '+w.reserve;$('wl1').classList.toggle('active',index!==3);$('wl2').classList.toggle('active',index===3);$('scope').classList.remove('on');$('crosshair').classList.remove('ads');player.aiming=false;camera.fov=76;camera.updateProjectionMatrix();audio.equip();}
77: function syncMatchTimer(){const seconds=Math.ceil(matchTime);if(seconds!==hudMatchSecond){hudMatchSecond=seconds;$('matchTimer').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}}
78: function syncHud(){const w=weapons[weaponIndex];$('scoreBlue').textContent=blueScore;$('scoreRed').textContent=redScore;syncMatchTimer();$('healthfill').style.width=`${player.health}%`;$('hud').classList.toggle('hurt',player.health<35);$('ammoMag').textContent=w.mag;$('ammoMag').classList.toggle('low',w.mag<=Math.ceil(w.magSize*.2));$('ammoRes').textContent='/ '+w.reserve;$('fragCount').textContent='×'+player.frag;$('reloadHint').classList.toggle('show',player.reloading);}
79: function pushFeed(killer,victim,team='red'){const row=document.createElement('div');row.className='kf';row.innerHTML=`<b>${killer}</b><span> ELIMINATED </span><i>${victim}</i>`;$('killfeed').prepend(row);while($('killfeed').children.length>5)$('killfeed').lastChild.remove();setTimeout(()=>row.remove(),6500);}
80: function startMatch(){audio.init();audio.click();active=true;paused=false;ended=false;matchTime=360;hudMatchSecond=-1;blueScore=redScore=0;player.health=100;player.alive=true;player.kills=player.deaths=player.score=player.shots=player.hits=player.streak=0;player.frag=selectedClass===2?1:2;player.pos.set(0,1.72,12);player.vel.set(0,0,0);player.yaw=Math.PI;player.pitch=0;weapons.forEach(w=>{w.mag=w.magSize;w.reserve=w.kind==='sniper'?40:180;});weaponIndex=selectedClass===2?2:selectedClass===1?1:0;spawnBots();$('menu').classList.add('hidden');$('endscreen').classList.add('hidden');$('pause').classList.add('hidden');$('death').classList.remove('on');$('hud').classList.remove('hidden');$('clickcatch').classList.add('hidden');$('killfeed').innerHTML='';setWeapon(weaponIndex);syncHud();requestPointer();}
81: function requestPointer(){if(active&&!paused&&document.pointerLockElement!==$('game'))$('game').requestPointerLock?.();}
82: function pauseMatch(){if(!active||ended)return;paused=true;$('pause').classList.remove('hidden');document.exitPointerLock?.();}
83: function resumeMatch(){paused=false;$('pause').classList.add('hidden');requestPointer();}
84: function finishMatch(){ended=true;active=false;document.exitPointerLock?.();const win=blueScore>=redScore;$('endResult').textContent=win?'VICTORY':'DEFEAT';$('endResult').className=win?'win':'loss';$('esKills').textContent=player.kills;$('esDeaths').textContent=player.deaths;$('esKd').textContent=(player.kills/Math.max(1,player.deaths)).toFixed(2);$('esScore').textContent=player.score;$('esAcc').textContent=Math.round(player.hits/Math.max(1,player.shots)*100)+'%';$('endscreen').classList.remove('hidden');}
85: function startReload(){const w=weapons[weaponIndex];if(player.reloading||w.mag===w.magSize||w.reserve<=0)return;player.reloading=true;player.reloadAt=performance.now()/1000+w.reload;audio.reload(weaponIndex===1);syncHud();}
86: function completeReload(){const w=weapons[weaponIndex],need=w.magSize-w.mag,take=Math.min(need,w.reserve);w.mag+=take;w.reserve-=take;player.reloading=false;syncHud();}
87: function cameraForward(){return new THREE.Vector3(-Math.sin(player.yaw)*Math.cos(player.pitch),Math.sin(player.pitch),-Math.cos(player.yaw)*Math.cos(player.pitch));}
88: function getBotRoot(object){while(object&&object!==scene){if(bots.includes(object))return object;object=object.parent;}return null;}
89: function visibleTarget(target){const origin=camera.position.clone(),delta=target.clone().sub(origin),distance=delta.length();raycaster.set(origin,delta.normalize());const hits=raycaster.intersectObjects(solids.map(s=>s.mesh),false);return !hits.length||hits[0].distance>distance;}
90: function showHit(kill=false){$('hitmarker').classList.add('show');hitTimer=.16;if(kill){$('killconfirm').classList.add('show');killTimer=.85;}}
91: function damagePlayer(amount,source){if(!player.alive||!active)return;player.health-=amount;player.lastDamage=performance.now()/1000;damageFlash=.45;$('hurt').style.opacity='.78';audio.hurt();const arcs=$('dmgArcs');const arc=document.createElement('i');arc.className='arc';arc.style.transform=`rotate(${Math.random()*360}deg)`;arc.style.opacity='.9';arcs.appendChild(arc);setTimeout(()=>arc.remove(),650);if(player.health<=0)killPlayer(source);syncHud();}
