function clearTouchInput(){touchMove.x=touchMove.y=0;touchFireHeld=false;touchAimHeld=false;movePointerId=lookPointerId=null;mouseHeld=false;$('moveNub').style.transform='translate(-50%,-50%)';document.querySelectorAll('#touchControls .down').forEach(button=>button.classList.remove('down'));setAiming(false);}
function syncTouchLayout(){const enabled=active&&!ended&&touchLayoutActive();$('touchControls').classList.toggle('hidden',!enabled);if(!enabled)clearTouchInput();}
function updateMovePad(event){const pad=$('movePad'),rect=pad.getBoundingClientRect(),radius=Math.min(rect.width,rect.height)*.34,cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=event.clientX-cx,dy=event.clientY-cy,length=Math.hypot(dx,dy),scale=length>radius?radius/length:1,x=dx*scale,y=dy*scale;touchMove.x=clamp(x/radius,-1,1);touchMove.y=clamp(-y/radius,-1,1);$('moveNub').style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;}
function handleTouchAction(action){if(action==='fire'){touchFireHeld=true;fireWeapon();return;}if(action==='aim'){touchAimHeld=true;setAiming(true);return;}if(action==='jump'){if(player.alive)player.vel.y=Math.max(player.vel.y,6.2);return;}if(action==='reload')startReload();if(action==='grenade')throwGrenade();if(action==='knife')knife();if(action==='swap')setWeapon(weaponIndex===3?0:3);if(action==='pause')pauseMatch();if(action==='streak0')deployStreak(0);if(action==='streak1')deployStreak(1);if(action==='streak2')deployStreak(2);}

