await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
let id=0;const pending=new Map();ws.onmessage=async event=>{const message=JSON.parse(typeof event.data==='string'?event.data:await event.data.text());if(message.id&&pending.has(message.id)){pending.get(message.id)(message);pending.delete(message.id);}};
const call=(method,params={})=>new Promise(resolve=>{const requestId=++id;pending.set(requestId,resolve);ws.send(JSON.stringify({id:requestId,method,params}));});
const evaluate=async expression=>{const response=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(response.error||response.result?.exceptionDetails)throw new Error(JSON.stringify(response));return response.result.result.value;};
await call('Emulation.setDeviceMetricsOverride',{width:960,height:540,deviceScaleFactor:1,mobile:true,screenOrientation:{type:'landscapePrimary',angle:90}});
