if(report.viewport[0]>1280||report.viewport[0]!==960||report.viewport[1]!==540||!report.coarse||!report.landscape||!report.matchActive||report.touchControlsDisplay==='none'||report.touchControlsHidden||!report.allButtonsInBounds)throw new Error(`Touch layout validation failed: ${JSON.stringify(report)}`);
